package com.dlt.predictor.auth;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.stereotype.Service;import java.time.Instant;import java.util.*;import java.util.concurrent.ConcurrentHashMap;
@Service public class AuthService{private final Map<String,UserAccount>users=new ConcurrentHashMap<>();private final BCryptPasswordEncoder encoder=new BCryptPasswordEncoder();AuthService(){users.put("admin",new UserAccount("admin",encoder.encode(System.getenv().getOrDefault("BOOTSTRAP_ADMIN_PASSWORD","admin")),UserAccount.Role.ADMIN,UserAccount.Status.APPROVED,true,Instant.now()));}public void register(String u,String p){if(users.containsKey(u))throw new IllegalArgumentException("用户名已存在");users.put(u,new UserAccount(u,encoder.encode(p),UserAccount.Role.USER,UserAccount.Status.PENDING,false,Instant.now()));}public UserAccount login(String u,String p){var a=Optional.ofNullable(users.get(u)).orElseThrow(()->new IllegalArgumentException("用户名或密码错误"));if(a.status()!=UserAccount.Status.APPROVED)throw new IllegalArgumentException("账户尚未通过审核或已禁用");if(!encoder.matches(p,a.passwordHash()))throw new IllegalArgumentException("用户名或密码错误");return a;}public List<UserAccount>pending(){return users.values().stream().filter(x->x.status()==UserAccount.Status.PENDING).toList();}public void approve(String u,boolean approved){var a=users.get(u);if(a==null)throw new IllegalArgumentException("用户不存在");users.put(u,new UserAccount(u,a.passwordHash(),a.role(),approved?UserAccount.Status.APPROVED:UserAccount.Status.REJECTED,a.mustChangePassword(),a.createdAt()));}}
